export const VIRGIN_1885_EVIDENCE =
  "The Virgin of the World of Hermes Mercurius Trismegistus, translated by Anna Kingsford and Edward Maitland (London: George Redway, 1885), first edition; public domain (Kingsford d. 1888, Maitland d. 1897). Taken from an e-text of the book (the Global Grey edition, archive.org virgin-of-the-world-of-hermes-mercurius-trismagistus) and compared word by word with a second OCR of the same e-text (archive.org the-virgin-of-the-world-of-hermes-mercurius-trismagistus) and with the archive.org OCR of Google's scan of an 1885 copy (1885-kingsford-maitland-virgin-of-the-world). The two e-text copies descend from one transcription, so the 1885 scan is the only independent witness. Where the other two outvote the e-text their reading is taken (once); the places where they disagree were read, and the doubtful ones read on the 1885 page images; the corrections by hand (dropped one-letter words before drop capitals, words the e-text shares wrongly, lost closing brackets, OCR of ornaments, two Greek words) are listed in scripts/texts/virgin-of-the-world.py. The footnotes, Ménard's and the translators', are left out; the translators' notes printed in the text in square brackets are kept. Italic and small capitals are not marked.";

const INTRO_EVIDENCE =
  "The first section of Kingsford's Introduction, as the archive divides it (the Introduction, pp. xix–xxx, has no sections of its own), from its opening to 'the curse of Eva' on p. xxi. The Introduction's 1885 setting was compared with the 1885 scan and one e-text copy only, since the other copy lacks it.";

function englishLayer(unit: VirginUnit): CorpusLayer {
  const where =
    unit.id === "intro"
      ? `the Introduction, pp. ${unit.firstPage}–${unit.lastPage}`
      : `${VIRGIN_TREATISE_TITLES[unit.treatise]}, Part ${unit.numeral}, ${pages(unit)}`;
  return {
    key: "eng-1885",
    layer: unit.id === "intro" ? "primary_text" : "translation",
    sourceKey: "kingsford-maitland-1885",
    content: unit.text,
    language: "English",
    licence: "public_domain",
    evidence: `${VIRGIN_1885_EVIDENCE} (${where})${unit.id === "intro" ? ` ${INTRO_EVIDENCE}` : ""}`,
  };
}

function pages(unit: VirginUnit): string {
  return unit.firstPage === unit.lastPage ? `p. ${unit.firstPage}` : `pp. ${unit.firstPage}–${unit.lastPage}`;
}

const MENARD: CorpusLayer = citedLayer(
  "fra-menard-1866",
  "menard-hermes-1866",
  "Louis Ménard, Hermès Trismégiste (Paris: Didier, 1866)",
  "The French version Kingsford and Maitland say they 'used, but not entirely followed' (p. ii); public domain, but not read for this import, so cited only.",
);

