function unitPassage(unit: VirginUnit): CorpusPassage {
  const meta = UNITS[unit.id];
  const key = `${BOOK}.${unit.id}`;
  const parentKey = unit.id === "intro" ? BOOK : `${BOOK}.${unit.treatise}`;
  const where = unit.id === "intro" ? `An Introduction to the Virgin of the World (first section), pp. ${unit.firstPage}–${unit.lastPage}` : `${VIRGIN_TREATISE_TITLES[unit.treatise]}, Part ${unit.numeral}, ${pages(unit)}`;
  return {
    key,
    parentKey,
    divisionKind: "part",
    label: meta.label,
    reference: `The Virgin of the World (London, 1885), ${where}`,
    sourceKey: "kingsford-maitland-1885",
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [englishLayer(unit)],
    themes: meta.themes.map(([themeKey, note]) => ({ themeKey, note })),
    images: imagesFor(VIRGIN_IMAGES, key),
  };
}

const TREATISE_ORDER = ["kore", "ascl", "def", "tat", "ammon", "frag"];

function buildPassages(): CorpusPassage[] {
  const passages: CorpusPassage[] = [
    {
      key: BOOK,
      divisionKind: "book",
      label: "The Virgin of the World (London, 1885)",
      reference:
        "The Virgin of the World of Hermes Mercurius Trismegistus, now first rendered into English, with essay, introductions and notes, by Dr. Anna Kingsford and Edward Maitland (London: George Redway, 1885), xxx + 154 pp.",
      sourceKey: "kingsford-maitland-1885",
      summary:
        "The first English version of the Korē Kosmou and of other Hermetic writings, made in 1885 by Anna Kingsford and Edward Maitland, founders of the Hermetic Society, with Louis Ménard's French version beside them: the Korē Kosmou, the Asclepius, Corpus Hermeticum XVI–XVIII as 'The Definitions of Asclepios', and fragments from Stobaeus, Cyril, the Suda and Lactantius, with Maitland's essays and Kingsford's Introduction.",
      notes:
        "A nineteenth-century translation, not an ancient witness: it renders Greek and Latin texts through Ménard's French ('used, but not entirely followed', p. ii), and its essays and notes give the translators' esoteric reading, which the archive records as context. Not imported: Maitland's essays 'The Hermetic Books' (pp. i–viii) and 'The Hermetic System and the Significance of its Present Revival' (pp. ix–xviii); Kingsford's Introduction after its first section (pp. xxi–xxx); the footnotes, Ménard's, Kingsford's and the publisher Robert H. Fryar's. The book opens with a frontispiece of a many-breasted Isis captioned 'Virgin of the World' and ends '[Published under the auspices of the Hermetic Society.]' (p. 154).",
      verificationStatus: "unverified",
      layers: [MENARD],
      dates: [PUBLISHED],
      images: imagesFor(VIRGIN_IMAGES, BOOK),
    },
  ];
  const intro = VIRGIN_UNITS.find((u) => u.id === "intro")!;
  passages.push(unitPassage(intro));
  for (const treatise of TREATISE_ORDER) {
    const key = `${BOOK}.${treatise}`;
    const units = VIRGIN_UNITS.filter((u) => u.treatise === treatise);
    const first = units[0];
    const last = units[units.length - 1];
    passages.push({
      key,
      parentKey: BOOK,
      divisionKind: "treatise",
      label: VIRGIN_TREATISE_TITLES[treatise],
      reference: `The Virgin of the World (London, 1885), ${VIRGIN_TREATISE_TITLES[treatise]}, Parts ${first.numeral}–${last.numeral}, pp. ${first.firstPage}–${last.lastPage}`,
      sourceKey: "kingsford-maitland-1885",
      summary: TREATISES[treatise].summary,
      notes: TREATISES[treatise].notes,
      verificationStatus: "unverified",
      layers: [],
      dates: TREATISE_DATES[treatise],
      images: imagesFor(VIRGIN_IMAGES, key),
    });
    passages.push(...units.map(unitPassage));
  }
  return passages;
}

