function asclepiusLinks(): CorpusLink[] {
  return Object.entries(ASCLEPIUS_CHAPTERS).flatMap(([part, chapters]) =>
    chapters.map((chapter) => ({
      key: `vow-ascl-${part}-mead-ascl-${chapter}`,
      from: `${BOOK}.ascl.${part}`,
      to: `herm.ascl.${chapter}`,
      connectionClass: "direct_textual_parallel",
      similarities: `Part ${roman(Number(part))} of the 1885 'Treatise on Initiations' renders the matter of chapter ${chapter} of the Asclepius in Mead's numbering: the same teaching, in the same order.`,
      differences: `${TWO_TRANSLATIONS} The 1885 division into fifteen parts follows Ménard and does not fall at Mead's chapter divisions, and the 1885 English often paraphrases where Mead keeps closer to the Latin.${ASCLEPIUS_DIFFERENCES[Number(part)] ? ` ${ASCLEPIUS_DIFFERENCES[Number(part)]}` : ""}`,
      wordingComparable: "partly",
      meaningComparable: "yes",
      transmissionEvidence: "Both are translations of the Latin Asclepius, which Augustine quotes early in the fifth century; the 1885 English through Ménard's French.",
      commonSourceNote: COMMON.ascl,
      reviewStatus: "proposed",
    }) satisfies CorpusLink),
  );
}

function roman(n: number): string {
  const table: [number, string][] = [[10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]];
  let out = "";
  for (const [value, numeral] of table) {
    while (n >= value) {
      out += numeral;
      n -= value;
    }
  }
  return out;
}

